function buildAxis(dirMath, lenNeg, lenPos, tickDirMath, tickMax) {
  const d0 = new THREE.Vector3(dirMath[0], dirMath[1], dirMath[2]);
  const td = new THREE.Vector3(tickDirMath[0], tickDirMath[1], tickDirMath[2]);
  const a = P(-d0.x * lenNeg, -d0.y * lenNeg, -d0.z * lenNeg);
  const b = P(d0.x * lenPos, d0.y * lenPos, d0.z * lenPos);
  makeBar(a, b, 0.016, axisSolid);

  const h = 0.16;          // tick half-length → 0.32 units overall
  for (let i = -tickMax; i <= tickMax; i++) {
    if (i === 0) continue;
    const c = [d0.x * i, d0.y * i, d0.z * i];
    makeBar(
      P(c[0] - td.x * h, c[1] - td.y * h, c[2] - td.z * h),
      P(c[0] + td.x * h, c[1] + td.y * h, c[2] + td.z * h),
      0.018, axisSolid
